(()=>{const root=document.documentElement;const random=()=>String(Math.floor(Math.random()*360));let hue=null;const reload=performance.getEntriesByType("navigation")[0]?.type==="reload";try{hue=reload?null:localStorage.getItem("accent-hue");if(hue===null){hue=random();localStorage.setItem("accent-hue",hue);}}catch{hue=hue??random();}root.dataset.faqeAccentHue=hue;const set=(name,value)=>root.style.setProperty(name,value);if(!root.hasAttribute("data-faqe-pin-theme")){const dark=matchMedia("(prefers-color-scheme: dark)").matches;const[bg,fg,mute,tint]=dark?["#1e1f20","#f2f2f2","#9ca3af","8%"]:["#ffffff","#1a1a1a","#6b7280","5%"];root.dataset.faqeScheme=dark?"dark":"light";set("--bg-color",`color-mix(in srgb,var(--accent-color) ${tint},${bg})`);set("--fg-color",fg);set("--glitch-color",fg);set("--mute-color",mute);set("--tint",tint);}if(!root.hasAttribute("data-faqe-pin-accent")){const h=Number(hue);const accent=`hsl(${h} 65% 50%)`;set("--accent-color",accent);set("--chromatic-a",accent);set("--chromatic-b",`hsl(${(h+150)%360} 65% 55%)`);set("--interactive-color",`hsl(${h} 65% ${root.dataset.faqeScheme==="light"?38:62}%)`);}})();